-- GENERATED by pipeline/make_dbt_staging.py from sources.json
-- and the extract's club folders; edit them or it, never this file.
{{ config(materialized='table') }}
-- Every suggested hikes row of the clubs' registered feeds, APIs and
-- WordPress and wiki sources that pipeline/make_dbt_staging.py stages, one
-- row each, unfiltered: a `union all by name` of every
-- stg_<folder>__suggested_hikes it writes. The branch list is the
-- registry's, written by the generator from sources.json and the extract's
-- club folders, so a layer registered later joins by running it again.
-- Nothing here is filtered for publication: whatever reads it keeps
-- int_sources__publication's verdict, the one home of may_publish.
select
    source_key,
    club,
    hike_key,
    name,
    link,
    properties,
    _loaded_at
from {{ ref('stg_cdtc__suggested_hikes') }}
union all by name
